<script setup lang="ts">
import {computed,nextTick,onMounted,ref,watch} from 'vue';import {useHistoryOverlay} from '../composables/useHistoryOverlay';import {useSessionStore,type RoundEffects,type Round} from '../stores/session';import {useRunStore} from '../stores/run';import type {useConversationController} from '../composables/useConversationController';import ChatMessage from '../components/ChatMessage.vue';import RoundToolbar from '../components/RoundToolbar.vue';import RoundActionDialog from '../components/RoundActionDialog.vue';import {useVisibleRefresh} from '../composables/useVisibleRefresh';import AsyncState from './AsyncState.vue';
const props=defineProps<{conversationId:string;controller:ReturnType<typeof useConversationController>}>(),session=useSessionStore(),run=useRunStore(),draft=ref(''),scroller=ref<HTMLElement>(),nearBottom=ref(true),newMessages=ref(false),error=ref(''),effects=ref<string[]>([]),roundBusy=ref(false),dialog=ref<{kind:'rollback'|'edit';id:string;question:string;index:number}|null>(null);
const mode=computed(()=>session.currentMode()),busy=computed(()=>run.inputLocked||props.controller.submitting.value||Boolean(session.activeRuns[props.conversationId]));
const dialogOpen=computed({get:()=>Boolean(dialog.value),set:value=>{if(!value)dialog.value=null;}});useHistoryOverlay(dialogOpen);
async function load(){if(props.controller.activeConversation.value!==props.conversationId)await session.openConversation(props.conversationId);else session.saveCurrentId(props.conversationId);draft.value=session.draftFor(props.conversationId);}
onMounted(load);watch(()=>props.conversationId,load);watch(draft,value=>session.saveDraft(props.conversationId,value));
useVisibleRefresh(()=>session.syncConversation(props.conversationId),()=>props.controller.activeConversation.value!==props.conversationId);
function onScroll(){const e=scroller.value;if(e){nearBottom.value=e.scrollHeight-e.scrollTop-e.clientHeight<100;if(nearBottom.value)newMessages.value=false;}}
async function latest(){nearBottom.value=true;newMessages.value=false;await nextTick();if(scroller.value)scroller.value.scrollTop=scroller.value.scrollHeight;}
watch(()=>session.currentMessages.map(m=>m.text+m.status).join('|'),async()=>{if(nearBottom.value)await latest();else newMessages.value=true;});
async function send(){const text=draft.value;if(!text.trim()||busy.value)return;nearBottom.value=true;void props.controller.submit(text,mode.value);}
function key(e:KeyboardEvent){if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();void send();}}
function describe(result:RoundEffects|undefined){if(!result)return [];return [...result.notes,...result.reverted.map(r=>'已回退沙盒对象 '+r.objectId),...result.rejectedPlans.map(id=>'已作废待确认方案 '+id),...result.notReverted.map(r=>'未回退 '+r.objectId+'：'+r.reason),...result.blocked.map(r=>'原系统已提交，需人工处理：'+r.planId+' '+r.objects.map(o=>o.id).join('、'))];}
async function remove(round:Round){if(busy.value||!round.userMessage||!confirm('删除本轮提问与回答，作废未确认方案。已提交业务不会撤销。继续？'))return;roundBusy.value=true;const result=await session.deleteRound(props.conversationId,round.userMessage.id);roundBusy.value=false;if(result.ok)effects.value=describe(result.effects);else error.value=result.message||'删除未成功';}
function openRound(kind:'rollback'|'edit',round:Round,index:number){if(!round.userMessage||busy.value||mode.value!=='task')return;dialog.value={kind,id:round.userMessage.id,question:round.userMessage.text,index:index+1};error.value='';}
async function confirmRound(input:{text:string;revertEffects:boolean}){if(!dialog.value||roundBusy.value)return;roundBusy.value=true;const selected={...dialog.value},result=await session.rollbackRound(props.conversationId,selected.id,input.revertEffects);roundBusy.value=false;if(!result.ok){error.value=result.message||'回档失败，已保留修改内容';return;}effects.value=describe(result.effects);dialog.value=null;if(selected.kind==='edit'){draft.value=input.text;await props.controller.submit(input.text,'task');}}
watch(()=>run.runStatus,value=>{if(value!=='running')draft.value=session.draftFor(props.conversationId);});
</script>
<template><div class="mobile-conversation"><div class="mobile-conversation-heading"><b>{{session.conversations.find(c=>c.id===conversationId)?.title||'会话'}}</b><span>{{mode==='chat'?'聊天会话 · 只读':'工作会话 · 本人确认办理'}} · 模式已确定</span><small>会话 {{conversationId}}</small></div><div ref="scroller" class="mobile-messages" @scroll.passive="onScroll"><p v-for="(line,i) in effects" :key="i" class="mobile-warning">{{line}}</p><p v-if="error||controller.error.value" role="alert">{{error||controller.error.value}}</p><AsyncState :loading="session.messagesLoading" :error="session.currentMessagesError||''" @retry="session.syncConversation(conversationId)"><p v-if="!session.currentMessages.length" class="mobile-state">{{mode==='chat'?'询问本人可读的事实。':'说明要查询或办理的事项，提交业务前会展示待确认方案。'}}</p><article v-for="(round,index) in session.currentRounds" :key="round.key" class="mobile-round"><ChatMessage v-for="message in round.messages" :key="message.id" :msg="message" @retry="draft=round.userMessage?.text||''"/><RoundToolbar :index="index+1" :can-rewind="mode==='task'" :busy="busy||roundBusy" :actionable="Boolean(round.userMessage)" @remove="remove(round)" @rollback="openRound('rollback',round,index)" @edit="openRound('edit',round,index)"/></article></AsyncState></div><button v-if="newMessages" class="mobile-new-messages" @click="latest">有新消息 · 查看</button><form class="mobile-composer" @submit.prevent="send"><label class="sr-only" for="mobile-question">输入问题</label><textarea id="mobile-question" v-model="draft" rows="2" maxlength="3000" :disabled="busy||Boolean(session.currentMessagesError)" :placeholder="mode==='chat'?'输入查询问题…':'输入要查询或办理的事项…'" @keydown="key"/><button v-if="busy" type="button" @click="controller.stop">停止</button><button v-else class="mobile-primary" :disabled="!draft.trim()||Boolean(session.currentMessagesError)" type="submit">发送</button><small v-if="session.activeRuns[conversationId]&&!run.inputLocked">服务端仍在生成，保留运行编号 {{session.activeRuns[conversationId]}}；刷新回查。</small></form><RoundActionDialog :open="Boolean(dialog)" :kind="dialog?.kind||'rollback'" :round-index="dialog?.index||1" :question="dialog?.question||''" :busy="roundBusy" :error="error" :has-business-writes="true" @cancel="dialog=null" @confirm="confirmRound"/></div></template>
